from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/log', methods=['POST'])
def log_message():
    data = request.get_json()
    print(data)  # Debugging: Print the received data to check input format
    return jsonify({"status": "Log message successful"}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

# Example of input sanitization to prevent log injection
def sanitize_input(message):
    # Replace newline characters to prevent log injection
    return message.replace('\n', ' ').replace('\r', '')

# Usage in the log_message function
message = sanitize_input(data['message'])
